// Generated by vibelang from src/features/presence/metrics.vibe; the migrate flow writes it again with each batch.
// What presence counts in the browser (docs/observability.md#browser). No attribute carries an id, a login or a place.
import * as Metric from "effect/Metric";
/** Rooms this browser joined, by `outcome`: `joined`. */
export const joins = Metric.counter("smithers_web_presence_joins", {
    description: "Branch rooms this browser joined",
    incremental: true,
});
/** Rooms that closed on this browser for good, by the `code` they closed with. */
export const closes = Metric.counter("smithers_web_presence_closes", {
    description: "Branch rooms that closed for good on this browser, by close code",
    incremental: true,
});
